(function () {
  'use strict';
  try {
    if (window.__iceBlackGround) return;
    window.__iceBlackGround = 1;
    var queued = false;
    function paint(el) {
      if (!el || !el.style) return;
      var s = el.style;
      if (s.getPropertyValue('background-color') !== 'rgb(0, 0, 0)' || s.getPropertyPriority('background-color') !== 'important')
        s.setProperty('background-color', '#000', 'important');
      if (s.getPropertyValue('background-image') !== 'none' || s.getPropertyPriority('background-image') !== 'important')
        s.setProperty('background-image', 'none', 'important');
    }
    function applyAll() {
      queued = false;
      try {
        var d = document;
        paint(d.documentElement); paint(d.body);
        paint(d.getElementById('bod')); paint(d.getElementById('can'));
      } catch (e) {}
    }
    function schedule() {
      if (queued) return;
      queued = true;
      (window.requestAnimationFrame || setTimeout)(applyAll, 50);
    }
    function start() {
      applyAll();
      try {
        var mo = new MutationObserver(schedule);
        var d = document;
        [d.documentElement, d.body, d.getElementById('bod'), d.getElementById('can')].forEach(function (el) {
          if (el) mo.observe(el, { attributes: true, attributeFilter: ['style', 'class'] });
        });
      } catch (e) {}
      var n = 0, t = setInterval(function () { applyAll(); if (++n >= 20) clearInterval(t); }, 1000);
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
    else start();
  } catch (e) {}
})();

/* ice perf f3: uses ONLY the game's own localStorage key "particles" (0=off,1=low,2=high; game default 2).
   Read by the client at every game start (reset()). No built-ins patched, no intervals, client.js untouched. */
(function () {
  try {
    if (window.__icePerf) return; window.__icePerf = 1;
    var ls = window.localStorage;
    if (ls && ls.getItem('particles') !== '0') ls.setItem('particles', '0');
  } catch (e) {}
})();

